        "id": "create_shipment",
        "description": "Create a new parcel or pallet shipment",
        "direction": "consumer_to_provider",
        "request": {
          "method": "POST",
          "path": "/v1/shipments",
          "headers": {
            "Authorization": {
              "required": true,
              "pattern": "^Bearer .+$"
            },
            "Idempotency-Key": {
              "required": true,
              "pattern": "^.{1,255}$"
            }
          },
          "body": {
            "$ref": "#/schemas/CreateShipmentRequest"
          }
        },
        "responses": {
          "201": {
            "body": {
              "$ref": "#/schemas/Shipment"
            }
          },
          "400": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          },
          "422": {
            "body": {
              "$ref": "#/schemas/Error"
            }
          }
        },
        "stub": {
          "default_status": 201,
          "body": {
            "id": "shp_{{seq}}",
            "reference": "{{request.body.reference}}",
            "status": "CREATED",
            "shipment_type": "{{request.body.shipment_type}}",
            "weight_g": "{{request.body.weight_g}}",
            "size": "{{request.body.size}}",
            "postcode": "{{request.body.postcode}}",
            "city": "{{request.body.city}}",
            "country": "{{request.body.country}}",
            "address_line": "{{request.body.address_line}}",
            "phone": "{{request.body.phone}}",
            "contact_name": "{{request.body.contact_name}}",
            "created_at": "{{now}}"
          },
          "idempotent_on_header": "Idempotency-Key"
        }
      }
