        "name": "spokes_phone_to_parcelly",
        "from": "consumer",
        "to": "provider",
        "mapping": {
          "description": "Normalize Polish phone formats to +48XXXXXXXXX (9 digits)",
          "rule": "Strip all non-digits, ensure starts with 48, pad/truncate to 9 digits after 48, prefix +"
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings/-",
      "value": {
        "name": "spokes_address_to_parcelly",
        "from": "consumer",
        "to": "provider",
        "mapping": {
          "description": "Parse free-text Polish address into postcode NN-NNN, city, address_line",
          "rule": "Extract postcode regex ^\\d{2}-\\d{3}$, next token as city (NFC normalize), rest as address_line"
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings/-",
      "value": {
        "name": "spokes_weight_kg_to_parcelly_g",
