        "to": "provider",
        "mapping": {
          "description": "Convert kg with 3 decimals to integer grams",
          "rule": "weight_g = Math.round(weight_kg * 1000)"
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings/-",
      "value": {
        "name": "spokes_weight_to_parcelly_size",
        "from": "consumer",
        "to": "provider",
        "mapping": {
          "description": "Map weight in grams to Parcelly size A/B/C",
          "rule": "A if ≤5000g, B if 5001-15000g, C if 15001-25000g, else pallet required"
        }
      }
    },
    {
      "op": "add",
      "path": "/semantic_mappings/-",
      "value": {
        "name": "spokes_shipment_type_selection",
        "from": "consumer",
        "to": "provider",
        "mapping": {
          "description": "Select parcel vs pallet based on total weight",
          "rule": "parcel if total_weight_g ≤ 25000, else pallet (cargo bikes >25kg go as pallet)"
        }
      }
    },
