    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D10",
        "text": "Parcelly rejects shipments with parcel.weight_g > 25000 with 422 WEIGHT_LIMIT_EXCEEDED. Consumer must reject orders >25kg before calling create_shipment (H7).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D11",
        "text": "Parcelly requires parcel.size to match weight_g: A for 1-5000g, B for 5001-15000g, C for 15001-25000g. Mismatch returns 422 SIZE_WEIGHT_MISMATCH. Consumer sends size A for all shipments (H6).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D12",
        "text": "Parcelly validates receiver.address.postcode matches receiver.address.city using internal Polish postcode-city map (NFC normalized, case-insensitive). Mismatch returns 422 POSTCODE_CITY_MISMATCH. Consumer trusts extraction and accepts rejections (H3).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D13",
        "text": "Parcelly requires receiver.phone to match ^\\+48\\d{9}$ exactly. Invalid format returns 422 INVALID_PHONE. Consumer normalizes phone before calling (D6).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D14",
        "text": "Parcelly requires receiver.address.country exactly 'PL'. All Spokes orders are domestic Poland. Consumer hardcodes 'PL' (H2).",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D15",
        "text": "Parcelly rejects requests with unknown fields in request body with 400 INVALID_REQUEST (additionalProperties: false on all schemas). Consumer must not send extra fields.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D16",
        "text": "Parcelly validates in strict order: schema -> phone format -> postcode format -> weight limit -> size-weight match -> postcode-city match. First failure returns its error code.",
        "owner": "provider"
      }
    },
    {
      "op": "add",
      "path": "/decisions/-",
      "value": {
        "id": "D17",
        "text": "Parcelly idempotency: Idempotency-Key scoped by partner. Blank key = no key (new shipment each call). Keys of 4xx responses are NOT stored (retry with same key creates new shipment). Keys >255 chars return 400 INVALID_IDEMPOTENCY_KEY. Consumer uses order ID as idempotency key (D9).",
        "owner": "provider"
      }
    },
