{"path": "app/services/parcelly.py", "content": "import hashlib
import hmac
import json
import logging
from typing import Any, Dict

import httpx

from app.core.config import get_settings

logger = logging.getLogger(__name__)


class ParcellyClient:
    def __init__(self, base_url: str, api_key: str, webhook_secret: str):
        self.base_url = base_url
        self.api_key = api_key
        self.webhook_secret = webhook_secret
        self.client = httpx.Client(base_url=base_url, timeout=30.0)

    def _auth_headers(self) -> Dict[str, str]:
        return {
            "Authorization": f"Bearer {self.api_key}",
        }

    def create_shipment(
        self,
        reference: str,
        address_line: str,
        postcode: str,
        city: str,
        country: str,
        phone: str,
        weight_g: int,
        size: str | None = None,
        pallet_type: str | None = None,
        idempotency_key: str | None = None,
    ) -> Dict[str, Any]:
        """Create a shipment with Parcelly.

        Returns the shipment data as dict.
        """
        payload: Dict[str, Any] = {
            "reference": reference,
            "address_line": address_line,
            "postcode": postcode,
            "city": city,
            "country": country,
            "phone": phone,
        }
        if size is not None:
            payload["parcel"] = {"weight_g": weight_g, "size": size}
        else:
            payload["pallet"] = {"weight_g": weight_g, "pallet_type": pallet_type}  # type: ignore[arg-type]

        headers = self._auth_headers()
        if idempotency_key:
            headers["Idempotency-Key"] = idempotency_key

        response = self.client.post(
            "/v1/shipments",
            json=payload,
            headers=headers,
        )
        response.raise_for_status()
        return response.json()

    def register_webhook(self, url: str, secret: str) -> Dict[str, Any]:
        payload = {"url": url, "secret": secret}
        response = self.client.post(
            "/v1/webhooks",
            json=payload,
            headers=self._auth_headers(),
        )
        response.raise_for_status()
        return response.json()

    def verify_webhook_signature(self, header: str, body: bytes) -> bool:
        """Verify the X-Parcelly-Signature header.

        Expected format: sha256=<hex>
        """
        try:
            scheme, sig = header.split("=", 1)
            if scheme.lower() != "sha256":
                return False
        except ValueError:
            return False

        mac = hmac.new(
            key=self.webhook_secret.encode(),
            msg=body,
            digestmod=hashlib.sha256,
        )
        expected = mac.hexdigest()
        return hmac.compare_digest(expected, sig)


settings = get_settings()


def get_parcelly_client() -> ParcellyClient:
    return ParcellyClient(
        base_url=settings.PARCELLY_BASE_URL,
        api_key=settings.PARCELLY_API_KEY,
        webhook_secret=settings.PARCELLY_WEBHOOK_SECRET,
    )"}

