{"path": "/workspace/repo/src/validation.js", "content": "import Ajv from "ajv";
import { ApiError } from "./errors.js";

const MAX_PARCEL_WEIGHT_G = 25000;
const MIN_PALLET_WEIGHT_G = 25001;
const MAX_PALLET_WEIGHT_G = 1000000;
const SIZE_LIMITS_G = Object.freeze({ A: 5000, B: 15000, C: 25000 });
const ADVANCEABLE_STATUSES = Object.freeze(["COLLECTED", "IN_TRANSIT", "DELIVERED", "RETURNED"]);

const PHONE_PATTERN = /^\+48\d{9}$/;
const POSTCODE_PATTERN = /^\d{2}-\d{3}$/;

const text = (maxLength) => ({ type: "string", minLength: 1, maxLength });

// Base schema for common fields
const baseShipmentSchema = {
  type: "object",
  required: ["reference", "address_line", "postcode", "city", "country", "phone"],
  additionalProperties: false,
  properties: {
    reference: text(64),
    address_line: text(200),
    postcode: { type: "string", pattern: POSTCODE_PATTERN },
    city: text(80),
    country: { type: "string", enum: ["PL"] },
    phone: { type: "string", pattern: PHONE_PATTERN },
    email: { type: "string", format: "email" },
  },
};

// Parcel-specific schema
const parcelSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "parcel"],
  properties: {
    ...baseShipmentSchema.properties,
    parcel: {
      type: "object",
      required: ["weight_g", "size"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: 1, maximum: MAX_PARCEL_WEIGHT_G },
        size: { type: "string", enum: ["A", "B", "C"] },
      },
    },
  },
};

// Pallet-specific schema
const palletSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "pallet"],
  properties: {
    ...baseShipmentSchema.properties,
    pallet: {
      type: "object",
      required: ["weight_g", "pallet_type"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: MIN_PALLET_WEIGHT_G, maximum: MAX_PALLET_WEIGHT_G },
        pallet_type: { type: "string", enum: ["EUR"] },
      },
    },
  },
};

// Combined schema: either parcel or pallet (but not both)
const shipmentRequestSchema = {
  oneOf: [
    { ...parcelSchema, additionalProperties: false },
    { ...palletSchema, additionalProperties: false },
  ],
};

const webhookRegistrationSchema = {
  type: "object",
  required: ["url", "secret"],
  additionalProperties: false,
  properties: {
    url: { type: "string", format: "uri" },
    secret: { type: "string", minLength: 32 },
  },
};

const sandboxPartnerSchema = {
  type: "object",
  required: ["name"],
  additionalProperties: false,
  properties: {
    name: text(120),
    api_key: text(256),
    flags: { type: "object", additionalProperties: { type: "boolean" } },
  },
};

const advanceSchema = {
  type: "object",
  required: ["to"],
  additionalProperties: false,
  properties: {
    to: { type: "string", enum: ADVANCEABLE_STATUSES },
  },
};

const ajv = new Ajv({ allErrors: true });
const validators = {
  shipment: ajv.compile(shipmentRequestSchema),
  webhook: ajv.compile(webhookRegistrationSchema),
  sandboxPartner: ajv.compile(sandboxPartnerSchema),
  advance: ajv.compile(advanceSchema),
};

function describe(error) {
  const path = error.instancePath || "/";
  const extra = error.params?.additionalProperty;
  return extra
    ? `${path} must not have additional property '${extra}'`
    : `${path} ${error.message}`;
}

function assertSchema(validator, body) {
  if (!validator(body)) {
    const errors = validator.errors;
    if (errors && errors.length) {
      // For oneOf, we want to show the first error that matches? We'll just take the first.
      throw new ApiError(400, "INVALID_REQUEST", describe(errors[0]));
    } else {
      throw new ApiError(400, "INVALID_REQUEST", "Invalid request");
    }
  }
}

function assertReceiverFormats(receiver) {
  // This function is no longer used in the new validation, but we keep it for compatibility.
  // Actually, we don't have a receiver field anymore. We'll leave it as is but it won't be called.
  if (!PHONE_PATTERN.test(receiver.phone)) {
    throw new ApiError(422, "INVALID_PHONE", "Receiver phone must have the format +48XXXXXXXXX");
  }
  if (!POSTCODE_PATTERN.test(receiver.address.postcode)) {
    throw new ApiError(422, "INVALID_POSTCODE", "Postcode must have the format NN-NNN");
  }
}

function assertPostcodeMatchesCity(address) {
  // This function is also not used in the new validation because we moved the check to validateShipmentRequest.
  // We'll keep it for now.
  if (!postcodeMatchesCity(address.postcode, address.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${address.postcode} does not belong to ${address.city}`,
    );
  }
}

export function sizeForWeight(weightG) {
  const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => weightG <= limit);
  return match ? match[0] : null;
}

export function validateShipmentRequest(body) {
  assertSchema(validators.shipment, body);

  // Additional validation: weight limits and size-weight match for parcel
  if ("parcel" in body) {
    const { weight_g: weightG, size } = body.parcel;
    if (weightG > MAX_PARCEL_WEIGHT_G) {
      throw new ApiError(
        422,
        "WEIGHT_LIMIT_EXCEEDED",
        `Parcel weight ${weightG} g exceeds the limit of ${MAX_PARCEL_WEIGHT_G} g`,
      );
    }
    if (sizeForWeight(weightG) !== size) {
      throw new ApiError(
        422,
        "SIZE_WEIGHT_MISMATCH",
        `Size ${size} does not match parcel weight ${weightG} g`,
      );
    }
  }

  // Additional validation: weight limits for pallet
  if ("pallet" in body) {
    const { weight_g: weightG } = body.pallet;
    if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
      throw new ApiError(
        422,
        "PALLET_WEIGHT_OUT_OF_RANGE",
        `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
      );
    }
  }

  // Postcode-city validation (using the address_line? Actually we have address_line, postcode, city as separate fields)
  // We need to validate that the postcode matches the city.
  // We have the postcode and city directly in the body.
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validatePalletRequest(body) {
  // This function is used for pallet-specific validation in the sandbox? Actually, the shipments.js uses validatePalletRequest for pallet shipments.
  // We'll reuse the same logic as in validateShipmentRequest but only for pallet.
  assertSchema(validators.shipment, body); // This will check that it matches either parcel or pallet schema.
  // Ensure it's a pallet (not parcel)
  if (!("pallet" in body)) {
    throw new ApiError(400, "INVALID_REQUEST", "Missing pallet");
  }
  const { weight_g: weightG } = body.pallet;
  if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
    throw new ApiError(
      422,
      "PALLET_WEIGHT_OUT_OF_RANGE",
      `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
    );
  }
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validateWebhookRegistration(body) {
  assertSchema(validators.webhook, body);
  let url;
  try {
    url = new URL(body.url);
  } catch {
    url = null;
  }
  if (url === null || !["http:", "https:"].includes(url.protocol)) {
    throw new ApiError(400, "INVALID_WEBHOOK_URL", "Webhook url must be an absolute http(s) URL");
  }
}

export function validateSandboxPartner(body) {
  assertSchema(validators.sandboxPartner, body);
}

export function validateAdvance(body) {
  assertSchema(validators.advance, body);
}"}

