import { STATUS_CHANGED_EVENT } from "./webhooks.js";

const PARCEL_PRICES_GR = Object.freeze({ A: 1299, B: 1599, C: 1999 });
const PALLET_PRICE_GR = 8900;

const SERVICES = Object.freeze({
  parcel: {
    idPrefix: "shp",
    trackingPrefix: "PCL",
    validate: validateShipmentRequest,
    price: (body) => PARCEL_PRICES_GR[body.parcel.size],
  },
  pallet: {
    idPrefix: "shp", // keep same id pattern as per Shipment schema
    trackingPrefix: "PAL",
    validate: validatePalletRequest,
    price: () => PALLET_PRICE_GR,
  },
});

export function serializeShipment(shipment) {
  return {
    id: shipment.id,
    reference: shipment.reference,
    status: shipment.status,
    tracking_number: shipment.trackingNumber,
    created_at: shipment.createdAt,
  };
}

function shipmentNotFound() {
  return new ApiError(404, "SHIPMENT_NOT_FOUND", "Shipment not found");
}

export function createShipmentService({ partners, webhooks }) {
  const shipments = new Map();
  const idempotencyKeys = new Map();
  const charges = [];
  const counters = { parcel: 0, pallet: 0 };

  return {
    create(partner, serviceName, body, idempotencyKey) {
      const scopedKey = idempotencyKey ? `${partner.id}:${idempotencyKey}` : null;
      if (scopedKey !== null && idempotencyKeys.has(scopedKey)) {
        return { shipment: shipments.get(idempotencyKeys.get(scopedKey)), replayed: true };
      }
      const service = SERVICES[serviceName];
      service.validate(body);
      counters[serviceName] += 1;
      const number = counters[serviceName];
      const now = new Date().toISOString();
      const shipment = {
        id: `${service.idPrefix}_${number}`,
        service: serviceName,
        partnerId: partner.id,
        reference: body.reference,
        status: "CREATED",
        trackingNumber: `${service.trackingPrefix}${number}PL`,
        priceGr: service.price(body),
        createdAt: now,
        updatedAt: now,
      };
      shipments.set(shipment.id, shipment);
      charges.push({
        shipmentId: shipment.id,
        partnerId: partner.id,
        reference: shipment.reference,
        amountGr: shipment.priceGr,
        chargedAt: now,
      });
      if (scopedKey !== null) {
        idempotencyKeys.set(scopedKey, shipment.id);
      }
      return { shipment, replayed: false };
    },

    getForPartner(partner, id) {
      const shipment = shipments.get(id);
      return shipment && shipment.partnerId === partner.id ? shipment : null;
    },

    findLatestByReference(reference, partner = null) {
      const shipment = [...shipments.values()].findLast(
        (candidate) =>
          candidate.reference === reference &&
          (partner === null || candidate.partnerId === partner.id),
      );
      return shipment ?? null;
    },

    get(id) {
      return shipments.get(id) ?? null;
    },

    advance(shipment, status) {
      if (shipment.status === status) {
        return shipment;
      }
      shipment.status = status;
      shipment.updatedAt = new Date().toISOString();
      const webhook = partners.get(shipment.partnerId)?.webhook;
      if (webhook) {
        webhooks.dispatch(webhook, {
          event: STATUS_CHANGED_EVENT,
          shipment_id: shipment.id,
          reference: shipment.reference,
          status: shipment.status,
          occurred_at: shipment.updatedAt,
        });
      }
      return shipment;
    },

    chargesFor(reference) {
      const matching = charges.filter((charge) => charge.reference === reference);
      return {
        reference,
        count: matching.length,
        total_gr: matching.reduce((total, charge) => total + charge.amountGr, 0),
      };
    },

    reset() {
      shipments.clear();
      idempotencyKeys.clear();
      charges.length = 0;
      counters.parcel = 0;
      counters.pallet = 0;
    },
  };
}

function idempotencyKeyFrom(request) {
  const value = request.get("idempotency-key");
  if (value === undefined) {
    return null;
  }
  const trimmed = value.trim();
  if (trimmed.length > 255) {
    throw new ApiError(
      400,
      "INVALID_IDEMPOTENCY_KEY",
      "Idempotency-Key must be at most 255 characters",
    );
  }
  return trimmed === "" ? null : trimmed;
}

export function createShipmentsRouter({ shipments }) {
  const router = express.Router();

  router.post("/shipments", (request, response) => {
    let serviceName;
    if ("parcel" in request.body) {
      serviceName = "parcel";
    } else if ("pallet" in request.body) {
      serviceName = "pallet";
    } else {
      throw new ApiError(400, "INVALID_REQUEST", "Missing parcel or pallet");
    }
    const { shipment, replayed } = shipments.create(
      request.partner,
      serviceName,
      request.body,
      idempotencyKeyFrom(request),
    );
    if (replayed) {
      response.set("Idempotent-Replayed", "true");
    }
    response.status(201).json(serializeShipment(shipment));
  });

  router.get("/shipments", (request, response) => {
    const reference = request.query.reference;
    if (typeof reference !== "string" || reference === "") {
      throw new ApiError(400, "REFERENCE_REQUIRED", "Query parameter 'reference' is required");
    }
    const shipment = shipments.findLatestByReference(reference, request.partner);
    if (shipment === null) {
      throw shipmentNotFound();
    }
    response.json(serializeShipment(shipment));
  });

  router.get("/shipments/:id", (request, response) => {
    const shipment = shipments.getForPartner(request.partner, request.params.id);
    if (shipment === null) {
      throw shipmentNotFound();
    }
    response.json(serializeShipment(shipment));
  });

  return router;
}"}

{"path": "/workspace/repo/src/validation.js", "content": "import Ajv from "ajv";
import { ApiError } from "./errors.js";
import { postcodeMatchesCity } from "./postcodes.js";

const MAX_PARCEL_WEIGHT_G = 25000;
const MIN_PALLET_WEIGHT_G = 25001;
const MAX_PALLET_WEIGHT_G = 1000000;
const SIZE_LIMITS_G = Object.freeze({ A: 5000, B: 15000, C: 25000 });
const ADVANCEABLE_STATUSES = Object.freeze(["COLLECTED", "IN_TRANSIT", "DELIVERED", "RETURNED"]);

const PHONE_PATTERN = "^\\\\+48\\\\d{9}$"; // string for JSON schema: ^\\+48\\d{9}$
const POSTCODE_PATTERN = "^\\\\d{2}-\\\\d{3}$"; // string: ^\\d{2}-\\d{3}$

// Base schema for common fields (reference, address_line, postcode, city, country, phone, email)
const baseShipmentSchema = {
  type: "object",
  required: ["reference", "address_line", "postcode", "city", "country", "phone"],
  additionalProperties: false,
  properties: {
    reference: { type: "string", minLength: 1 },
    address_line: { type: "string", minLength: 1 },
    postcode: { type: "string", pattern: POSTCODE_PATTERN },
    city: { type: "string", minLength: 1 },
    country: { type: "string", enum: ["PL"] },
    phone: { type: "string", pattern: PHONE_PATTERN },
    email: { type: "string", format: "email" },
  },
};

// Parcel-specific schema
const parcelSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "parcel"],
  properties: {
    ...baseShipmentSchema.properties,
    parcel: {
      type: "object",
      required: ["weight_g", "size"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: 1, maximum: MAX_PARCEL_WEIGHT_G },
        size: { type: "string", enum: ["A", "B", "C"] },
      },
    },
  },
};

// Pallet-specific schema
const palletSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "pallet"],
  properties: {
    ...baseShipmentSchema.properties,
    pallet: {
      type: "object",
      required: ["weight_g", "pallet_type"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: MIN_PALLET_WEIGHT_G, maximum: MAX_PALLET_WEIGHT_G },
        pallet_type: { type: "string", enum: ["EUR"] },
      },
    },
  },
};

const webhookRegistrationSchema = {
  type: "object",
  required: ["url", "secret"],
  additionalProperties: false,
  properties: {
    url: { type: "string", format: "uri" },
    secret: { type: "string", minLength: 32 },
  },
};

const sandboxPartnerSchema = {
  type: "object",
  required: ["name"],
  additionalProperties: false,
  properties: {
    name: { type: "string", minLength: 1, maxLength: 120 },
    api_key: { type: "string", minLength: 1, maxLength: 256 },
    flags: { type: "object", additionalProperties: { type: "boolean" } },
  },
};

const advanceSchema = {
  type: "object",
  required: ["to"],
  additionalProperties: false,
  properties: {
    to: { type: "string", enum: ADVANCEABLE_STATUSES },
  },
};

const ajv = new Ajv({ allErrors: true });
const validators = {
  parcel: ajv.compile(parcelSchema),
  pallet: ajv.compile(palletSchema),
  webhook: ajv.compile(webhookRegistrationSchema),
  sandboxPartner: ajv.compile(sandboxPartnerSchema),
  advance: ajv.compile(advanceSchema),
};

function describe(error) {
  const path = error.instancePath || "/";
  const extra = error.params?.additionalProperty;
  return extra
    ? `${path} must not have additional property '${extra}'`
    : `${path} ${error.message}`;
}

function assertSchema(validator, body) {
  if (!validator(body)) {
    const errors = validator.errors;
    if (errors && errors.length) {
      throw new ApiError(400, "INVALID_REQUEST", describe(errors[0]));
    } else {
      throw new ApiError(400, "INVALID_REQUEST", "Invalid request");
    }
  }
}

export function sizeForWeight(weightG) {
  const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => weightG <= limit);
  return match ? match[0] : null;
}

export function validateShipmentRequest(body) {
  // Validate against parcel schema
  assertSchema(validators.parcel, body);

  // Additional validation for parcel: weight limit and size-weight match
  const { weight_g: weightG, size } = body.parcel;
  if (weightG > MAX_PARCEL_WEIGHT_G) {
    throw new ApiError(
      422,
      "WEIGHT_LIMIT_EXCEEDED",
      `Parcel weight ${weightG} g exceeds the limit of ${MAX_PARCEL_WEIGHT_G} g`,
    );
  }
  if (sizeForWeight(weightG) !== size) {
    throw new ApiError(
      422,
      "SIZE_WEIGHT_MISMATCH",
      `Size ${size} does not match parcel weight ${weightG} g`,
    );
  }

  // Postcode-city validation
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validatePalletRequest(body) {
  // Validate against pallet schema
  assertSchema(validators.pallet, body);

  // Additional validation for pallet: weight range
  const { weight_g: weightG } = body.pallet;
  if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
    throw new ApiError(
      422,
      "PALLET_WEIGHT_OUT_OF_RANGE",
      `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
    );
  }

  // Postcode-city validation
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validateWebhookRegistration(body) {
  assertSchema(validators.webhook, body);
  let url;
  try {
    url = new URL(body.url);
  } catch {
    url = null;
  }
  if (url === null || !["http:", "https:"].includes(url.protocol)) {
    throw new ApiError(400, "INVALID_WEBHOOK_URL", "Webhook url must be an absolute http(s) URL");
  }
}

export function validateSandboxPartner(body) {
  assertSchema(validators.sandboxPartner, body);
}

export function validateAdvance(body) {
  assertSchema(validators.advance, body);
}"}

