{"path": "/workspace/repo/src/validation.js", "content": "import Ajv from "ajv";
import { ApiError } from "./errors.js";
import { postcodeMatchesCity } from "./postcodes.js";

const MAX_PARCEL_WEIGHT_G = 25000;
const MIN_PALLET_WEIGHT_G = 25001;
const MAX_PALLET_WEIGHT_G = 1000000;
const SIZE_LIMITS_G = Object.freeze({ A: 5000, B: 15000, C: 25000 });
const ADVANCEABLE_STATUSES = Object.freeze(["COLLECTED", "IN_TRANSIT", "DELIVERED", "RETURNED"]);

// Pattern strings for JSON schema (must be strings, not RegExp)
const PHONE_PATTERN = "^\\\\+48\\\\d{9}$";       // matches ^\\+48\\d{9}$
const POSTCODE_PATTERN = "^\\\\d{2}-\\\\d{3}$";   // matches ^\\d{2}-\\d{3}$
const EMAIL_PATTERN = "^[^@]+@[^@]+\\\\.[^@]+$"; // simple email pattern

// Base schema for common fields (reference, address_line, postcode, city, country, phone, email)
const baseShipmentSchema = {
  type: "object",
  required: ["reference", "address_line", "postcode", "city", "country", "phone"],
  additionalProperties: false,
  properties: {
    reference: { type: "string", minLength: 1 },
    address_line: { type: "string", minLength: 1 },
    postcode: { type: "string", pattern: POSTCODE_PATTERN },
    city: { type: "string", minLength: 1 },
    country: { type: "string", enum: ["PL"] },
    phone: { type: "string", pattern: PHONE_PATTERN },
    email: { type: "string", format: "email" }, // we will add custom format
  },
};

// Parcel-specific schema
const parcelSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "parcel"],
  properties: {
    ...baseShipmentSchema.properties,
    parcel: {
      type: "object",
      required: ["weight_g", "size"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: 1, maximum: MAX_PARCEL_WEIGHT_G },
        size: { type: "string", enum: ["A", "B", "C"] },
      },
    },
  },
};

// Pallet-specific schema
const palletSchema = {
  ...baseShipmentSchema,
  required: [...baseShipmentSchema.required, "pallet"],
  properties: {
    ...baseShipmentSchema.properties,
    pallet: {
      type: "object",
      required: ["weight_g", "pallet_type"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: MIN_PALLET_WEIGHT_G, maximum: MAX_PALLET_WEIGHT_G },
        pallet_type: { type: "string", enum: ["EUR"] },
      },
    },
  },
};

const webhookRegistrationSchema = {
  type: "object",
  required: ["url", "secret"],
  additionalProperties: false,
  properties: {
    url: { type: "string", format: "uri" }, // we will add custom format
    secret: { type: "string", minLength: 32 },
  },
};

const sandboxPartnerSchema = {
  type: "object",
  required: ["name"],
  additionalProperties: false,
  properties: {
    name: { type: "string", minLength: 1, maxLength: 120 },
    api_key: { type: "string", minLength: 1, maxLength: 256 },
    flags: { type: "object", additionalProperties: { type: "boolean" } },
  },
};

const advanceSchema = {
  type: "object",
  required: ["to"],
  additionalProperties: false,
  properties: {
    to: { type: "string", enum: ADVANCEABLE_STATUSES },
  },
};

const ajv = new Ajv({ allErrors: true });
// Add custom formats
ajv.addFormat("uri", (value) => {
  try {
    new URL(value);
    return true;
  } catch {
    return false;
  }
});
ajv.addFormat("email", (value) => {
  // Simple email validation
  return /^[^@]+@[^@]+.[^@]+$/.test(value);
});

const validators = {
  parcel: ajv.compile(parcelSchema),
  pallet: ajv.compile(palletSchema),
  webhook: ajv.compile(webhookRegistrationSchema),
  sandboxPartner: ajv.compile(sandboxPartnerSchema),
  advance: ajv.compile(advanceSchema),
};

function describe(error) {
  const path = error.instancePath || "/";
  const extra = error.params?.additionalProperty;
  return extra
    ? `${path} must not have additional property '${extra}'`
    : `${path} ${error.message}`;
}

function assertSchema(validator, body) {
  if (!validator(body)) {
    const errors = validator.errors;
    if (errors && errors.length) {
      // We'll take the first error and map it to our error codes
      const error = errors[0];
      let { keyword, instancePath, params } = error;
      // Remove leading slash from instancePath
      if (instancePath.startsWith('/')) {
        instancePath = instancePath.slice(1);
      }
      switch (keyword) {
        case "pattern":
          if (instancePath === "postcode") {
            throw new ApiError(422, "INVALID_POSTCODE", `Postcode must match pattern ${params.pattern}`);
          }
          if (instancePath === "phone") {
            throw new ApiError(422, "INVALID_PHONE", `Phone must match pattern ${params.pattern}`);
          }
          break;
        case "enum":
          if (instancePath === "country") {
            throw new ApiError(400, "INVALID_COUNTRY", `Country must be one of ${params.allowedValues.join(", ")}`);
          }
          break;
        case "additionalProperties":
          throw new ApiError(400, "INVALID_FIELDS", `Additional property ${params.additionalProperty} is not allowed`);
        case "required":
          // params.missingProperty is a string or array? In AJV 8, it's a string for single missing, array for multiple?
          // We'll assume the first missing property.
          const missing = Array.isArray(params.missingProperty) ? params.missingProperty[0] : params.missingProperty;
          throw new ApiError(400, "INVALID_REQUEST", `Missing required property: ${missing}`);
        default:
          throw new ApiError(400, "INVALID_REQUEST", error.message);
      }
    } else {
      throw new ApiError(400, "INVALID_REQUEST", "Invalid request");
    }
  }
}

export function sizeForWeight(weightG) {
  const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => weightG <= limit);
  return match ? match[0] : null;
}

export function validateShipmentRequest(body) {
  // Validate against parcel schema
  assertSchema(validators.parcel, body);

  // Additional validation for parcel: weight limit and size-weight match
  const { weight_g: weightG, size } = body.parcel;
  if (weightG > MAX_PARCEL_WEIGHT_G) {
    throw new ApiError(
      422,
      "WEIGHT_LIMIT_EXCEEDED",
      `Parcel weight ${weightG} g exceeds the limit of ${MAX_PARCEL_WEIGHT_G} g`,
    );
  }
  if (sizeForWeight(weightG) !== size) {
    throw new ApiError(
      422,
      "SIZE_WEIGHT_MISMATCH",
      `Size ${size} does not match parcel weight ${weightG} g`,
    );
  }

  // Postcode-city validation
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validatePalletRequest(body) {
  // Validate against pallet schema
  assertSchema(validators.pallet, body);

  // Additional validation for pallet: weight range
  const { weight_g: weightG } = body.pallet;
  if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
    throw new ApiError(
      422,
      "PALLET_WEIGHT_OUT_OF_RANGE",
      `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
    );
  }

  // Postcode-city validation
  if (!postcodeMatchesCity(body.postcode, body.city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${body.postcode} does not belong to ${body.city}`,
    );
  }
}

export function validateWebhookRegistration(body) {
  assertSchema(validators.webhook, body);
  let url;
  try {
    url = new URL(body.url);
  } catch {
    url = null;
  }
  if (url === null || !["http:", "https:"].includes(url.protocol)) {
    throw new ApiError(400, "INVALID_WEBHOOK_URL", "Webhook url must be an absolute http(s) URL");
  }
}

export function validateSandboxPartner(body) {
  assertSchema(validators.sandboxPartner, body);
}

export function validateAdvance(body) {
  assertSchema(validators.advance, body);
}"}

