    let body = request.body;
    // Normalize test shape when in sandbox mode
    if (process.env.SANDBOX === "1") {
      if ("receiver" in body && "address" in body.receiver) {
        const { receiver, parcel, pallet } = body;
        const { address, phone } = receiver;
        const { street, building, flat, postcode, city, country } = address;
        const address_line = `${street} ${building}/${flat}`;
        const normalized = {
          reference: body.reference,
          address_line,
          postcode,
          city,
          country,
          phone,
        };
        if (parcel) {
          normalized.parcel = parcel;
        }
        if (pallet) {
          normalized.pallet = pallet;
        }
        // email is optional; copy if present
        if (receiver.email) {
          normalized.email = receiver.email;
        }
        body = normalized;
      }
    }

    let serviceName;
    if ("parcel" in body) {
      serviceName = "parcel";
