{"path": "/workspace/repo/src/validation.js", "content": "import Ajv from "ajv";
import { ApiError } from "./errors.js";
import { postcodeMatchesCity } from "./postcodes.js";

const MAX_PARCEL_WEIGHT_G = 25000;
const MIN_PALLET_WEIGHT_G = 25001;
const MAX_PALLET_WEIGHT_G = 1000000;
const SIZE_LIMITS_G = Object.freeze({ A: 5000, B: 15000, C: 25000 });
const ADVANCEABLE_STATUSES = Object.freeze(["COLLECTED", "IN_TRANSIT", "DELIVERED", "RETURNED"]);

const PHONE_PATTERN = /^\+48\d{9}$/;
const POSTCODE_PATTERN = /^\d{2}-\d{3}$/;

const text = (maxLength) => ({ type: "string", minLength: 1, maxLength });

// Base schema for common fields
const baseShipmentSchema = {
  type: "object",
  required: ["reference", "address_line", "postcode", "city", "country", "phone"],
  additionalProperties: false,
  properties: {
    reference: text(64),
    address_line: text(120),
    postcode: { type: "string", pattern: "^\\d{2}-\\d{3}$" },
    city: text(80),
    country: { type: "string", const: "PL" },
    phone: { type: "string", pattern: "^\\+48\\d{9}$" },
    email: { type: "string", format: "email" },
    parcel: {
      type: "object",
      required: ["weight_g", "size"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: 1 },
        size: { type: "string", enum: ["A", "B", "C"] },
      },
    },
    pallet: {
      type: "object",
      required: ["weight_g", "pallet_type"],
      additionalProperties: false,
      properties: {
        weight_g: { type: "integer", minimum: 1 },
        pallet_type: { type: "string", enum: ["EUR"] },
      },
    },
  },
};

const ajv = new Ajv({ allErrors: true });
const baseValidator = ajv.compile(baseShipmentSchema);

function describe(error) {
  const path = error.instancePath || "/";
  const extra = error.params?.additionalProperty;
  return extra
    ? `${path} must not have additional property '${extra}'`
    : `${path} ${error.message}`;
}

function assertSchema(validator, body) {
  if (!validator(body)) {
    throw new ApiError(400, "INVALID_REQUEST", describe(validator.errors[0]));
  }
}

// Helper to validate phone format (already in schema but we keep for 422)
function assertPhoneFormat(phone) {
  if (!PHONE_PATTERN.test(phone)) {
    throw new ApiError(422, "INVALID_PHONE", "Receiver phone must have the format +48XXXXXXXXX");
  }
}

// Helper to validate postcode format (already in schema but we keep for 422)
function assertPostcodeFormat(postcode) {
  if (!POSTCODE_PATTERN.test(postcode)) {
    throw new ApiError(422, "INVALID_POSTCODE", "Postcode must have the format NN-NNN");
  }
}

// Helper to validate postcode matches city
function assertPostcodeMatchesCity(postcode, city) {
  if (!postcodeMatchesCity(postcode, city)) {
    throw new ApiError(
      422,
      "POSTCODE_CITY_MISMATCH",
      `Postcode ${postcode} does not belong to ${city}`,
    );
  }
}

// Helper to validate parcel weight limit
function assertParcelWeightLimit(weightG) {
  if (weightG > MAX_PARCEL_WEIGHT_G) {
    throw new ApiError(
      422,
      "WEIGHT_LIMIT_EXCEEDED",
      `Parcel weight ${weightG} g exceeds the limit of ${MAX_PARCEL_WEIGHT_G} g`,
    );
  }
}

// Helper to validate size matches weight
function assertSizeMatchesWeight(weightG, size) {
  const sizeForWeight = (w) => {
    const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => w <= limit);
    return match ? match[0] : null;
  };
  if (sizeForWeight(weightG) !== size) {
    throw new ApiError(
      422,
      "SIZE_WEIGHT_MISMATCH",
      `Size ${size} does not match parcel weight ${weightG} g`,
    );
  }
}

// Helper to validate pallet weight range
function assertPalletWeightRange(weightG) {
  if (weightG < MIN_PALLET_WEIGHT_G || weightG > MAX_PALLET_WEIGHT_G) {
    throw new ApiError(
      422,
      "PALLET_WEIGHT_OUT_OF_RANGE",
      `Pallet weight must be between ${MIN_PALLET_WEIGHT_G} g and ${MAX_PALLET_WEIGHT_G} g`,
    );
  }
}

// Main validation function for shipment request
export function validateShipmentRequest(body) {
  // Validate base schema (including optional parcel/pallet)
  assertSchema(baseValidator, body);

  // Ensure exactly one of parcel or pallet is present
  const hasParcel = !!body.parcel;
  const hasPallet = !!body.pallet;
  if (!(hasParcel ^ hasPallet)) {
    throw new ApiError(
      400,
      "INVALID_REQUEST",
      "Exactly one of 'parcel' or 'pallet' must be present",
    );
  }

  // Validate phone format (for 422)
  assertPhoneFormat(body.phone);
  // Validate postcode format (for 422)
  assertPostcodeFormat(body.postcode);
  // Validate postcode matches city
  assertPostcodeMatchesCity(body.postcode, body.city);

  if (hasParcel) {
    const { weight_g: weightG, size } = body.parcel;
    assertParcelWeightLimit(weightG);
    assertSizeMatchesWeight(weightG, size);
  } else {
    const { weight_g: weightG } = body.pallet;
    assertPalletWeightRange(weightG);
    // pallet_type is already validated by schema as EUR
  }
}

// Pallet request validation (used elsewhere? maybe not needed)
export function validatePalletRequest(body) {
  // We'll reuse the same logic but for pallet only
  assertSchema(baseValidator, body);
  if (!body.pallet) {
    throw new ApiError(400, "INVALID_REQUEST", "Missing pallet");
  }
  if (body.parcel) {
    throw new ApiError(400, "INVALID_REQUEST", "Parcel not allowed for pallet request");
  }
  assertPhoneFormat(body.phone);
  assertPostcodeFormat(body.postcode);
  assertPostcodeMatchesCity(body.postcode, body.city);
  const { weight_g: weightG } = body.pallet;
  assertPalletWeightRange(weightG);
}

// Webhook registration validation (unchanged)
export function validateWebhookRegistration(body) {
  // We'll keep simple validation; could reuse schema but we'll keep as is for now
  if (typeof body !== "object" || body === null) {
    throw new ApiError(400, "INVALID_REQUEST", "Body must be an object");
  }
  if (typeof body.url !== "string" || body.url.trim() === "") {
    throw new ApiError(400, "INVALID_REQUEST", "Missing or empty url");
  }
  if (typeof body.secret !== "string" || body.secret.length < 32) {
    throw new ApiError(400, "INVALID_REQUEST", "Secret must be at least 32 characters");
  }
  try {
    new URL(body.url);
  } catch {
    throw new ApiError(400, "INVALID_WEBHOOK_URL", "Webhook url must be an absolute http(s) URL");
  }
}

// Sandbox partner validation (unchanged)
export function validateSandboxPartner(body) {
  if (typeof body !== "object" || body === null) {
    throw new ApiError(400, "INVALID_REQUEST", "Body must be an object");
  }
  if (typeof body.name !== "string" || body.name.trim() === "") {
    throw new ApiError(400, "INVALID_REQUEST", "Missing or empty name");
  }
  if (body.api_key !== undefined && (typeof body.api_key !== "string" || body.api_key.trim() === "")) {
    throw new ApiError(400, "INVALID_REQUEST", "api_key must be a non-empty string if provided");
  }
  if (body.flags !== undefined && typeof body.flags !== "object") {
    throw new ApiError(400, "INVALID_REQUEST", "flags must be an object");
  }
}

// Advance validation (unchanged)
export function validateAdvance(body) {
  if (typeof body !== "object" || body === null) {
    throw new ApiError(400, "INVALID_REQUEST", "Body must be an object");
  }
  if (typeof body.to !== "string" || !ADVANCEABLE_STATUSES.includes(body.to)) {
    throw new ApiError(400, "INVALID_REQUEST", "Invalid status transition");
  }
}

// Size for weight helper (used elsewhere?)
export function sizeForWeight(weightG) {
  const match = Object.entries(SIZE_LIMITS_G).find(([, limit]) => weightG <= limit);
  return match ? match[0] : null;
}"}

