const BEARER_PATTERN = /^Bearer\s+(\S+)$/;

export function requirePartner(partners) {
  return (request, response, next) => {
    const authHeader = request.get("authorization");
    const match = BEARER_PATTERN.exec(authHeader ?? "");
    const providedKey = match ? match[1] : null;
    // Log for debugging
    console.log("[AUTH] Authorization header:", authHeader);
    console.log("[AUTH] Provided key:", providedKey);
    const partner = providedKey ? partners.findByApiKey(providedKey) : null;
    console.log("[AUTH] Partner found:", partner ? partner.apiKey : null);
    if (!partner) {
      // List all keys in the partners map for debugging
      const allKeys = [];
      partners.forEach((p) => allKeys.push(p.apiKey));
      console.log("[AVAILABLE KEYS]", allKeys);
      throw new ApiError(401, "UNAUTHORIZED", "Missing or invalid partner API key");
    }
    request.partner = partner;
    next();
  };
}"}

